      const chain=[];for(let current=node;current&&current.nodeType===1;current=current.parentElement){chain.unshift(current);if(current===root)break}
      let matrix=base;chain.forEach(current=>{const value=current.getAttribute("transform");if(value)matrix=matrixMultiply(matrix,transformMatrix(value))});
      const type=node.localName,geometry=type==="path"?{d:node.getAttribute("d")||""}:["polygon","polyline"].includes(type)?{points:node.getAttribute("points")||""}:Object.fromEntries((type==="rect"?["x","y","width","height"]:type==="circle"?["cx","cy","r"]:["cx","cy","rx","ry"]).map(name=>[name,Number(node.getAttribute(name))||0]));
      if(matrix.some((value,position)=>Math.abs(value-[1,0,0,1,0,0][position])>0.000001))geometry.matrix=matrix.map(value=>Number(value.toFixed(6)));
